func HasAgentToken() predicate.AgentEnrollment {
	return predicate.AgentEnrollment(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, AgentTokenTable, AgentTokenColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAgentTokenWith applies the HasEdge predicate on the "agent_token" edge with a given conditions (other predicates).
func HasAgentTokenWith(preds ...predicate.AgentToken) predicate.AgentEnrollment {
	return predicate.AgentEnrollment(func(s *sql.Selector) {
		step := newAgentTokenStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AgentEnrollment) predicate.AgentEnrollment {
	return predicate.AgentEnrollment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AgentEnrollment) predicate.AgentEnrollment {
	return predicate.AgentEnrollment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AgentEnrollment) predicate.AgentEnrollment {
	return predicate.AgentEnrollment(sql.NotPredicates(p))
}
